PACKED = ""

# -*- coding: utf-8 -*-
"""НДС выданных счетов-фактур: по расчётной ставке, а где её нет — из документа-основания.

У 209 из 295 счетов-фактур ставка в шапке пуста: это счета на отгрузку, где налог
живёт в строках документа-основания. У остальных ставка расчётная (20/120, 22/122) —
это авансовые, и там налог считается от суммы, как считает сама 1С.
"""
import base64
import gzip
import json
import re
from collections import defaultdict

from sqlalchemy import select

from app.database import async_session_factory
from app.models import AccountingDoc, Company

RATES = json.loads(gzip.decompress(base64.b64decode(PACKED)).decode('utf-8'))
FACTOR = {'20/120': 20 / 120, '22/122': 22 / 122, '20%': 20 / 120, '10/110': 10 / 110}
# «Реализация (акт, накладная, УПД) 1-0707 от 07.07.2026 12:00:00» → номер и дата.
BASIS_RE = re.compile(r'(?P<number>\S+)\s+от\s+(?P<date>\d{2}\.\d{2}\.\d{4})')


def num(v):
    try:
        return float(v or 0)
    except (TypeError, ValueError):
        return 0.0


import os

# Какой компании грузим. Дефолта нет намеренно: забытая переменная подписала бы
# данные одной компании другой — молча и без следа в цифрах.
SLUG = os.environ.get('COMPANY_SLUG')
if not SLUG:
    raise SystemExit('COMPANY_SLUG не задан: укажи slug компании (promizol, rti, ...)')


async def main():
    async with async_session_factory() as s:
        cid = (await s.execute(select(Company.id).where(Company.slug == SLUG))).scalar_one()
        docs = (await s.execute(select(AccountingDoc)
                                .where(AccountingDoc.company_id == cid))).scalars().all()

        by_key = defaultdict(list)
        for doc in docs:
            by_key[((doc.number or '').strip(), (doc.date or '')[:10],
                    doc.counterparty_inn or '')].append(doc)

        rate_of = {}
        for r in RATES:
            rate_of[(r['number'], r['date'])] = r['rate']

        for doc in docs:
            if doc.doc_type == 'vat_invoice_out':
                doc.vat_amount = 0

        by_rate = by_basis = 0
        for doc in docs:
            if doc.doc_type != 'vat_invoice_out' or num(doc.vat_amount):
                continue
            rate = rate_of.get(((doc.number or '').strip(), (doc.date or '')[:10]), '')
            if rate in FACTOR:
                doc.vat_amount = round(num(doc.amount) * FACTOR[rate], 2)
                by_rate += 1
                continue
            basis = (doc.details or {}).get('Основание') or ''
            m = BASIS_RE.search(basis)
            if not m:
                continue
            dd, mm, yy = m.group('date').split('.')
            for src in by_key.get((m.group('number'), '%s-%s-%s' % (yy, mm, dd),
                                   doc.counterparty_inn or ''), []):
                if src.id != doc.id and num(src.vat_amount):
                    doc.vat_amount = src.vat_amount
                    by_basis += 1
                    break

        await s.commit()
        rest = [d for d in docs if d.doc_type == 'vat_invoice_out']
        print('по расчётной ставке:', by_rate, '· из документа-основания:', by_basis)
        print('НДС заполнен у %d из %d, налог %.2f' % (
            sum(1 for d in rest if num(d.vat_amount)), len(rest),
            sum(num(d.vat_amount) for d in rest)))

        from app.models import VatEntry
        journal = [v for v in (await s.execute(select(VatEntry).where(
            VatEntry.company_id == cid, VatEntry.kind == 'issued'))).scalars()]
        dm, jm = defaultdict(float), defaultdict(float)
        for d in rest:
            dm[(d.date or '')[:7]] += num(d.vat_amount)
        for v in journal:
            jm[(v.doc_date or '')[:7]] += num(v.vat)
        bad = [(m, dm.get(m, 0) - jm.get(m, 0)) for m in sorted(set(dm) | set(jm))
               if abs(dm.get(m, 0) - jm.get(m, 0)) > 0.05]
        print('сверка с книгой продаж: %s' % ('сходится' if not bad else bad))


import asyncio
asyncio.run(main())
